const erro = $input.first().json;

// Tenta pegar o nome do arquivo do item original
const nomeArquivo = erro?.data[0]?.filename ?? 'desconhecido';
const tipoArquivo = erro?.data[0]?.mimetype ?? 'desconhecido';

return {
  "erro": `Falha no upload do arquivo.\n` +
  `Arquivo recebido: "${nomeArquivo}" (tipo: ${tipoArquivo})\n` +
  `Causa: ${erro?.error ?? 'Erro desconhecido no formulário'}\n` +
  `Verifique se o arquivo é um CSV válido e tente novamente.`
};

const items = $('Ler CSV').all();
const erros = [];
const resultados = [];

items.forEach((item, index) => {
  try {
    const data = Object.fromEntries(
      Object.entries(item.json).map(([key, value]) => [
        key.replace(/^\uFEFF/, '').trim(), // trim() pega espaços extras também
        value
      ])
    );

    if (!data['APRESENTAÇÃO'] && !data['CÓDIGO SAP']) {
      // Linha completamente vazia, ignora silenciosamente
      return;
    }

    const conteudo_semantico = `${data['APRESENTAÇÃO'] ?? ''}`;

    resultados.push({
      json: {
        conteudo_semantico,
        sap: data['CÓDIGO SAP'],
        nome: data['APRESENTAÇÃO'],
        principio_ativo: data['PRINCIPIO ATIVO'],
        familia: data['FAMÍLIA'],
        ncm: data['NCM (CLASS FISCAL)'],
        tipo: data['TIPO DE MEDICAMENTO'],
        tarja: data['TARJA'],
        qtde: data['QTDE'],
        precos: {
          icms_0:        { pf: data["ICMS 0 % (PF)"],              pmc: data["ICMS 0 % (PMC)"] },
          icms_12:       { pf: data["ICMS 12 %  (PF)"],            pmc: data["ICMS 12 % (PMC) "] },
          icms_17:       { pf: data["ICMS 17 % (PF)"],             pmc: data["ICMS 17 % (PMC)"] },
          icms_175:      { pf: data["ICMS 17,5 % (PF)"],           pmc: data["ICMS 17,5 % (PMC)"] },
          icms_18:       { pf: data["ICMS 18 %  (PF)"],            pmc: data["ICMS 18 %  (PMC)"] },
          icms_20:       { pf: data["ICMS 20 % (PF)"],             pmc: data["ICMS 20 % (PMC)"] },
          icms_17_ac_rr: { pf: data["ICMS 17 % (ALC) AC/RR (PF)"], pmc: data["ICMS 17 % (ALC) AC/RR (PMC)"] },
          icms_175_ro:   { pf: data["ICMS 17,5 % (ALC) RO (PF)"],  pmc: data["ICMS 17,5 % (ALC) RO (PMC)"] },
          icms_18_am_ap: { pf: data["ICMS 18 % (ALC) AM/AP (PF)"], pmc: data["ICMS 18 % (ALC) AM/AP (PMC)"] }
        },
        ean: data['CÓDIGO EAN'] ? String(data['CÓDIGO EAN']) : null,
        registro_ms: data['REGISTRO MS'] ? String(data['REGISTRO MS']) : null
      }
    });
  } catch (e) {
    erros.push(`Linha ${index + 1}: ${e.message}`);
  }
});

if (erros.length > 0 && resultados.length === 0) {
  return {'erro': `Todas as linhas falharam no processamento:\n${erros.join('\n')}`
}

if (erros.length > 0) {
  // Loga os erros parciais mas continua — você pode mudar isso para throw se quiser rigor total
  console.log(`Avisos (${erros.length} linhas ignoradas):\n${erros.join('\n')}`);
}

return resultados;

